-- ==============================================================================
-- SITIA - Migración de Base de Datos para Producción: Remitos de Devolución
-- Base de Datos: inventario_insumos_v1
-- Nomenclatura: nnnn_yyyy_DEV (Ej: 0001_2026_DEV)
-- Fecha: 2026-10-01 17:44:19
-- ==============================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- ------------------------------------------------------------------------------
-- 1. Estructura: Secuencia Anual de Devoluciones
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `remito_devolucion_secuencia` (
    `anio` INT NOT NULL,
    `ultimo` INT NOT NULL DEFAULT 0,
    PRIMARY KEY (`anio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------------------------
-- 2. Estructura: Cabecera de Remitos de Devolución
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `remitos_devolucion` (
    `id_remito_devolucion` INT NOT NULL AUTO_INCREMENT,
    `numero_devolucion` VARCHAR(50) NOT NULL,
    `id_remito_origen` INT NOT NULL,
    `fecha_devolucion` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `id_usuario_receptor` INT NOT NULL,
    `persona_entrega` VARCHAR(150) DEFAULT NULL,
    `observaciones` TEXT DEFAULT NULL,
    `remito_firmado` VARCHAR(255) DEFAULT NULL,
    `estado` ENUM('Confirmado', 'Anulado') NOT NULL DEFAULT 'Confirmado',
    `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (`id_remito_devolucion`),
    UNIQUE KEY `uk_numero_devolucion` (`numero_devolucion`),
    KEY `idx_remdev_origen` (`id_remito_origen`),
    KEY `idx_remdev_fecha` (`fecha_devolucion`),
    KEY `idx_remdev_usuario` (`id_usuario_receptor`),
    CONSTRAINT `fk_remdev_remito` FOREIGN KEY (`id_remito_origen`) REFERENCES `remitos` (`id_remito`) ON DELETE RESTRICT,
    CONSTRAINT `fk_remdev_usuario` FOREIGN KEY (`id_usuario_receptor`) REFERENCES `usuarios` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------------------------
-- 3. Estructura: Detalle de Insumos Devueltos
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `remitos_devolucion_detalle` (
    `id_remito_devolucion_detalle` INT NOT NULL AUTO_INCREMENT,
    `id_remito_devolucion` INT NOT NULL,
    `id_insumo` INT NOT NULL,
    `cantidad` INT NOT NULL DEFAULT 1,
    `destino` ENUM('disponible', 'baja') NOT NULL DEFAULT 'disponible',
    `motivo_baja` VARCHAR(255) DEFAULT NULL,
    `estado_fisico` VARCHAR(100) DEFAULT NULL,
    PRIMARY KEY (`id_remito_devolucion_detalle`),
    KEY `idx_remdev_det_rem` (`id_remito_devolucion`),
    KEY `idx_remdev_det_ins` (`id_insumo`),
    CONSTRAINT `fk_remdev_det_cab` FOREIGN KEY (`id_remito_devolucion`) REFERENCES `remitos_devolucion` (`id_remito_devolucion`) ON DELETE CASCADE,
    CONSTRAINT `fk_remdev_det_ins` FOREIGN KEY (`id_insumo`) REFERENCES `insumos` (`id_insumo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------------------------
-- 4. Aseguramiento de columna cantidad_devuelta en remitos_detalle (Idempotente)
-- ------------------------------------------------------------------------------
SET @col_exist = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'remitos_detalle' AND COLUMN_NAME = 'cantidad_devuelta');
SET @sql_stmt = IF(@col_exist = 0, 'ALTER TABLE remitos_detalle ADD COLUMN cantidad_devuelta INT NOT NULL DEFAULT 0 AFTER cantidad', 'SELECT "Columna cantidad_devuelta ya existe"');
PREPARE stmt FROM @sql_stmt;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

